<template>
  <CustomerWorkShell :title="type==='refund'?'退回物流':'订单物流'" :manager="manager" active="orders"><template v-if="logistics"><view class="cw-card"><text class="cw-subtitle">{{ orderId }}</text><text class="cw-scope">{{ type==='refund'?'全站退款申请的退回物流':'全站订单与拆单包裹' }}</text><text>{{ logistics.message }}</text></view><view v-for="(item,index) in packages" :key="item.orderId+'-'+index" class="cw-card"><view class="cw-row"><text class="cw-subtitle">{{ item.orderId }}</text><text class="cw-status">{{ stateLabels[item.trackingState] }}</text></view><view class="cw-row"><text>{{ item.expressName || '尚无快递公司' }}</text><text>{{ item.expressNo || '尚无运单号' }}</text></view><text class="cw-scope">{{ item.message }} · {{ sourceLabels[item.trackingSource] }}{{ item.lastUpdatedAt?' · '+customerWorkDate(item.lastUpdatedAt):'' }}</text><view v-for="(trace,i) in item.traces" :key="i" class="cw-divider cw-stack"><text>{{ trace.content }}</text><text class="cw-muted">{{ trace.time }} {{ trace.status }}</text></view><text v-if="!item.traces.length" class="cw-muted">{{ item.trackingState==='not_configured'?'物流服务尚未配置，暂无可验证的轨迹':'当前暂无物流轨迹' }}</text></view></template></CustomerWorkShell>
</template>
<script setup lang="ts">
import { computed,ref } from 'vue';import CustomerWorkShell from '@/components/customerWork/CustomerWorkShell.vue';import { useCustomerWork } from '@/composables/useCustomerWork';import { isCustomerWorkLogistics,customerWorkDate } from '@/utils/customerWork';import type { CustomerWorkLogistics } from '@/types/customerWork';
const logistics=ref<CustomerWorkLogistics|null>(null),orderId=ref(''),type=ref(''),packages=computed(()=>logistics.value?(logistics.value.packages.length?logistics.value.packages:[logistics.value]):[]),stateLabels={pending:'待查询',in_transit:'运输中',delivered:'已签收',exception:'物流异常',not_configured:'尚未配置',temporarily_unavailable:'暂时不可用'},sourceLabels={merchant:'订单记录',carrier:'快递服务',cache:'已验证缓存'};
const manager=useCustomerWork({page:'logistics',query(query){orderId.value=query.orderId!;type.value=query.type??'';},clear(){logistics.value=null;},async load(controller){const valid=controller.fence(),id=orderId.value,response=await controller.read(`orders/${encodeURIComponent(id)}/logistics`,isCustomerWorkLogistics,type.value?{type:type.value}:{});if(!valid())return;if(response.data.orderId!==id)throw Error('物流业务编号不匹配');logistics.value=response.data;}});
</script>
